private string GetGridTableName()
{
    if (rdoShowType1.Checked)
        return "STA_MixVoucher";
    return "STA_MixVoucherDetail";
}

private void ModifyGrid()
{
    Color clrChot = Color.FromArgb(255, 255, 204);
    Color clrTay = Color.FromArgb(204, 255, 204);

    for (int i = 0; i < gvData.Columns.Count; i++)
    {
        DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col =
            gvData.Columns[i] as DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn;
        if (col == null || col.FieldName == null || col.FieldName == "")
            continue;

        if (rdoShowType1.Checked && col.FieldName.EndsWith("_chot"))
        {
            col.AppearanceCell.BackColor = clrChot;
            col.AppearanceCell.Options.UseBackColor = true;
            col.AppearanceHeader.BackColor = clrChot;
            col.AppearanceHeader.Options.UseBackColor = true;
        }
        else if (rdoShowType1.Checked && col.FieldName.EndsWith("_tay"))
        {
            col.AppearanceCell.BackColor = clrTay;
            col.AppearanceCell.Options.UseBackColor = true;
            col.AppearanceHeader.BackColor = clrTay;
            col.AppearanceHeader.Options.UseBackColor = true;
        }
        else
        {
            col.AppearanceCell.BackColor = Color.Empty;
            col.AppearanceCell.Options.UseBackColor = false;
            col.AppearanceHeader.BackColor = Color.Empty;
            col.AppearanceHeader.Options.UseBackColor = false;
        }
    }
}

